from pathlib import Path
p=Path('outputs/kings-site/tools/build.py');s=p.read_text();start=s.index("home=f'''");end=s.index('\n<div class="ticker"',start)
new='''home=f\'''<section class="history-hero" aria-label="Kings of Kings concert history"><div class="history-heading"><p class="eyebrow"><span class="live-dot"></span> KINGS OF KINGS INTERNATIONAL</p><h1>THE NIGHTS.<br>THE LEGENDS.<br><em>THE LEGACY.</em></h1><p class="history-lead">Real artists. Unforgettable shows.<br>Step inside the Kings of Kings story.</p><div class="hero-actions"><a class="button gold" href="/studio/#history">Explore our history <span aria-hidden="true">↗</span></a><a class="text-link" href="/studio/#upcoming">Upcoming events →</a></div><p class="archive-intro">FROM THE KINGS ARCHIVE <span aria-hidden="true">⟶</span></p><div class="history-tabs" role="group" aria-label="Choose a featured show">{''.join(f'<button data-show="{i}" aria-pressed="{str(i==0).lower()}" class="show-tab {"selected" if i==0 else ""}"><span>0{i+1}</span>{esc(e["city"].split(",")[0])}</button>' for i,e in enumerate([events[2],events[1],events[0]]))}</div></div><div class="archive-stage">{''.join(f'<article class="show-feature" data-show-panel="{i}" {"" if i==0 else "hidden"}><div class="archive-frame"><span class="frame-label">ORIGINAL SHOW POSTER / {e["display"]}</span><a href="/events/{e["slug"]}/" aria-label="Explore {esc(e["title"])} in {esc(e["city"].split(",")[0])}">{image(e["image"],e["title"]+" original poster featuring "+", ".join(e["performers"][:3]),eager=i==0)}</a></div><div class="show-caption"><div><span class="eyebrow">{esc(e["city"])} · {e["display"]}</span><h2>{esc(e["venue"])}</h2><p>{esc(" · ".join(e["performers"][:3]))}</p></div><a href="/events/{e["slug"]}/" class="show-open" aria-label="Read the {esc(e["city"].split(",")[0])} show history">↗</a></div></article>' for i,e in enumerate([events[2],events[1],events[0]]))}</div><div class="history-bottom"><span>ROOTS. CULTURE. TRUTH. LOVE.</span><a href="#latest">MORE FROM THE ARCHIVE ↓</a></div></section>'''
s=s[:start]+new+s[end:];p.write_text(s)
